__global__ void copy_panel_to_factor_kernel(
        const float* source, float* factor, int leading_source) {
    constexpr int tile_size = 64;
    __shared__ float tile[tile_size][tile_size + 1];
    const int task = static_cast<int>(blockIdx.x);
    int tile_row = static_cast<int>(
        (sqrtf(8.0f * static_cast<float>(task) + 1.0f) - 1.0f)
        * 0.5f);
    int base = tile_row * (tile_row + 1) / 2;
    if (base > task) {
        --tile_row;
        base = tile_row * (tile_row + 1) / 2;
    } else if (base + tile_row + 1 <= task) {
        ++tile_row;
        base = tile_row * (tile_row + 1) / 2;
    }
    const int tile_col = task - base;
    const int row_base = tile_row * tile_size;
    const int col_base = tile_col * tile_size;
    for (int y = threadIdx.y; y < tile_size; y += blockDim.y) {
        for (int x = threadIdx.x; x < tile_size; x += blockDim.x) {
            unsigned destination = static_cast<unsigned>(
                __cvta_generic_to_shared(&tile[y][x]));
            const float* source_element = source
                + static_cast<int64_t>(row_base + y) * leading_source
                + col_base + x;
            asm volatile(
                "cp.async.ca.shared.global.L2::128B [%0], [%1], 4;\n"
                :: "r"(destination), "l"(source_element));
        }
    }
    asm volatile("cp.async.commit_group;\n" ::);
    asm volatile("cp.async.wait_group 0;\n" ::);
    __syncthreads();
    for (int y = threadIdx.y; y < tile_size; y += blockDim.y) {
        for (int x = threadIdx.x; x < tile_size; x += blockDim.x) {
            factor[
                row_base + x
                + static_cast<int64_t>(col_base + y) * 4096
            ] = tile[x][y];
        }
    }
}

